{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2168-09-28 21:33:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you tonight. Can you tell me what’s been going on with your headache?"
    },
    {
      "turn_number": 2,
      "time": "2168-09-28 21:35:00",
      "speaker": "Patient",
      "text": "It’s been going on for about three weeks. It started in the front and now it’s spreading to the back of my head and neck. It’s constant and really bad."
    },
    {
      "turn_number": 3,
      "time": "2168-09-28 21:37:00",
      "speaker": "Doctor",
      "text": "I see. Are you having any nausea, sensitivity to light or sound?"
    },
    {
      "turn_number": 4,
      "time": "2168-09-28 21:38:00",
      "speaker": "Patient",
      "text": "Yes, I’ve been nauseous and can’t keep my pain meds down. Light and noise make it worse. Today I even saw flashing lights in the corner of my eye."
    },
    {
      "turn_number": 5,
      "time": "2168-09-28 21:40:00",
      "speaker": "Doctor",
      "text": "That sounds like a migraine. You’ve had headaches like this before?"
    },
    {
      "turn_number": 6,
      "time": "2168-09-28 21:41:00",
      "speaker": "Patient",
      "text": "Yeah, maybe once a month. I used to take Imitrex, but my HIV meds don’t mix well with it."
    },
    {
      "turn_number": 7,
      "time": "2168-09-28 21:43:00",
      "speaker": "Doctor",
      "text": "That’s right, we can’t use Imitrex because of your HIV treatment. We’ll manage it another way. You had a CT scan in the ER—no bleeding or stroke. That’s good news."
    },
    {
      "turn_number": 8,
      "time": "2168-09-28 21:45:00",
      "speaker": "Patient",
      "text": "So it’s not something serious like a tumor?"
    },
    {
      "turn_number": 9,
      "time": "2168-09-28 21:46:00",
      "speaker": "Doctor",
      "text": "No, the scan looks clear. No mass or acute issue. Given your symptoms and history, this is most likely a migraine flare-up."
    },
    {
      "turn_number": 10,
      "time": "2168-09-28 22:15:00",
      "speaker": "Doctor",
      "text": "Your urine test showed signs of infection—bacteria and nitrites. We’re starting you on ciprofloxacin for a urinary tract infection."
    },
    {
      "turn_number": 11,
      "time": "2168-09-28 22:17:00",
      "speaker": "Patient",
      "text": "I haven’t had burning or urgency. Are you sure?"
    },
    {
      "turn_number": 12,
      "time": "2168-09-28 22:19:00",
      "speaker": "Doctor",
      "text": "Sometimes infections don’t cause symptoms, especially with chronic conditions. We treat it to prevent complications."
    },
    {
      "turn_number": 13,
      "time": "2168-09-29 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs look stable. Blood pressure is high at 165 over 105. We’re adding lisinopril to help control it."
    },
    {
      "turn_number": 14,
      "time": "2168-09-29 07:02:00",
      "speaker": "Patient",
      "text": "I didn’t know my BP was high. Should I be worried?"
    },
    {
      "turn_number": 15,
      "time": "2168-09-29 07:04:00",
      "speaker": "Doctor",
      "text": "Not right now. It’s common with pain and stress. We’ll monitor it. You’ll need to check it at your follow-up and get blood work for potassium."
    },
    {
      "turn_number": 16,
      "time": "2168-09-29 15:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re discharging you today. Keep taking your HIV meds, and now add lisinopril daily, cipro for two more days, and Zofran for nausea if needed."
    },
    {
      "turn_number": 17,
      "time": "2168-09-29 15:02:00",
      "speaker": "Patient",
      "text": "And my headache? What should I do if it comes back?"
    },
    {
      "turn_number": 18,
      "time": "2168-09-29 15:04:00",
      "speaker": "Doctor",
      "text": "Keep using acetaminophen and Zofran. Follow up with your primary doctor and neurology. Call if the headache worsens, or if you have weakness, vision changes, or confusion."
    },
    {
      "turn_number": 19,
      "time": "2168-09-29 15:06:00",
      "speaker": "Patient",
      "text": "Okay, I’ll make sure to do that. Thank you."
    },
    {
      "turn_number": 20,
      "time": "2168-09-29 15:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Rest well, take your meds, and keep your appointments."
    }
  ],
  "summary": {
    "admission_start": "2168-09-28 21:33:00",
    "admission_end": "2168-09-29 16:38:00",
    "summary_paragraph": "The patient was admitted for evaluation of a persistent headache lasting three weeks, associated with photophobia, phonophobia, nausea, and transient visual disturbances. A non-contrast head CT showed no acute intracranial pathology, supporting a diagnosis of migraine rather than structural or infectious causes. She was unable to take her usual migraine medication, Imitrex, due to interactions with her HIV regimen. During the admission, she was treated for an asymptomatic urinary tract infection with ciprofloxacin and started on lisinopril for newly detected hypertension. Her HIV remained well controlled, and other chronic conditions were managed without change. She was discharged home in good condition with instructions to follow up with her primary care provider and neurology for ongoing headache management.",
    "problems": [
      "Headache",
      "Urinary tract infection, site not specified",
      "Unspecified essential hypertension",
      "Chronic diastolic heart failure",
      "Congestive heart failure, unspecified",
      "Personal history of malignant neoplasm of ovary",
      "Chronic obstructive asthma, unspecified",
      "Personal history of urinary calculi",
      "Morbid obesity",
      "Lumbago",
      "Other chronic pain",
      "Osteoarthrosis, localized, not specified whether primary or secondary, lower leg",
      "Asymptomatic human immunodeficiency virus [HIV] infection status"
    ]
  }
}
